/* ---------- Ответы для самопроверки (считаются из тех же данных) ---------- */
const S = DS.sales.rows;
const ANS = {
  qty: sum(S.map(x => x[6])),
  revenue: sum(DS.salesRev),
  accTen: S.filter(x => x[5] === 'Аксессуары' && x[6] >= 10).length,
  bonus: sum(DS.staff.rows.map(x => x[5] >= 100 && x[3] >= 2 ? x[4] * 0.15 : x[5] >= 90 ? x[4] * 0.05 : 0)),
  vlookup: (() => { const p = Object.fromEntries(DS.catalog.rows.map(c => [c[0], c[3]])); return sum(DS.orders.rows.map(o => (p[o[2]] || 0) * o[3])); })(),
  dirty: DS.dirtyUnique,
  march: sum(S.map((x, i) => x[1].split('.')[1] === '03' ? DS.salesRev[i] : 0)),
  febCons: sum(DS.branches.map(b => sum(b.rows.map(r => r[2])))),
  maxRegion: (() => { const m = {}; S.forEach((x, i) => m[x[2]] = (m[x[2]] || 0) + DS.salesRev[i]); return Math.max(...Object.values(m)); })(),
  techShare: sum(S.map((x, i) => x[5] === 'Техника' ? DS.salesRev[i] : 0)) / sum(DS.salesRev) * 100,
  checkStd: stdevS(DS.checks.rows.map(x => x[1])),
  bin1500: DS.checks.rows.filter(x => x[1] > 1000 && x[1] <= 1500).length,
  planPct: sum(DS.plan.rows.map(x => x[3])) / sum(DS.plan.rows.map(x => x[2])) * 100,
  avgGrowth: (() => { const v = DS.dyn.rows.map(x => x[1]); return Math.pow(v[v.length - 1] / v[0], 1 / (v.length - 1)) * 100; })(),
  correl: correl(DS.adv.rows.map(x => x[1]), DS.adv.rows.map(x => x[2])),
  slope: slope(DS.adv.rows.map(x => x[2]), DS.adv.rows.map(x => x[1])),
  forecast: (() => { const y = DS.monthly.rows.map(x => x[2]), t = DS.monthly.rows.map(x => x[0]); return intercept(y, t) + slope(y, t) * 25; })(),
  bep: 450000 / (1200 - 700),
  lp: (() => { let best = 0; for (let x = 0; x <= 40; x++) for (let y = 0; y <= 100; y++) if (2 * x + y <= 100 && x + y <= 80) best = Math.max(best, 3000 * x + 2000 * y); return best; })(),
  bishAcc: sum(S.map((x, i) => x[2] === 'Бишкек' && x[5] === 'Аксессуары' ? DS.salesRev[i] : 0)),
  avgCheck: mean(DS.salesRev)
};


/* ---------- Ответы для вторых пар ---------- */
const quartileInc = (a, p) => { const s = [...a].sort((x, y) => x - y), h = (s.length - 1) * p, lo = Math.floor(h); return s[lo] + (h - lo) * ((s[lo + 1] ?? s[lo]) - s[lo]); };
function olsR2(ys, xs) { // множественная регрессия, R²
  const X = ys.map((_, i) => [1, ...xs.map(c => c[i])]), k = X[0].length;
  const A = Array.from({ length: k }, (_, i) => Array.from({ length: k + 1 }, (_, j) => j < k ? sum(X.map(r => r[i] * r[j])) : sum(X.map((r, t) => r[i] * ys[t]))));
  for (let i = 0; i < k; i++) { let p = i; for (let j = i + 1; j < k; j++) if (Math.abs(A[j][i]) > Math.abs(A[p][i])) p = j; [A[i], A[p]] = [A[p], A[i]]; for (let j = 0; j < k; j++) if (j !== i) { const f = A[j][i] / A[i][i]; for (let c = i; c <= k; c++) A[j][c] -= f * A[i][c]; } }
  const b = A.map((row, i) => row[k] / row[i]), my = mean(ys);
  const sse = sum(ys.map((y, t) => (y - sum(X[t].map((v, j) => v * b[j]))) ** 2)), sst = sum(ys.map(y => (y - my) ** 2));
  return 1 - sse / sst;
}
const regRev = reg => sum(S.map((x, i) => x[2] === reg ? DS.salesRev[i] : 0));
Object.assign(ANS, {
  avgPrice: mean(S.map(x => x[7])),
  rank10: DS.salesRev.filter(v => v > DS.salesRev[9]).length + 1,
  aboveAvg: DS.salesRev.filter(v => v > mean(DS.salesRev)).length,
  salesSenior: sum(DS.staff.rows.map(x => x[2] === 'Продажи' && x[3] >= 5 ? x[4] : 0)),
  ordAcc: (() => { const c = Object.fromEntries(DS.catalog.rows.map(r => [r[0], r])); return sum(DS.orders.rows.map(o => c[o[2]] && c[o[2]][2] === 'Аксессуары' ? c[o[2]][3] * o[3] : 0)); })(),
  weekend: S.filter(x => { const [d, m] = x[1].split('.').map(Number); const w = new Date(2026, m - 1, d).getDay(); return w === 0 || w === 6; }).length,
  oshQ1: sum(DS.branches[1].rows.map(r => r[1] + r[2] + r[3])),
  bishShare: regRev('Бишкек') / ANS.revenue * 100,
  june: sum(S.map((x, i) => x[1].split('.')[1] === '06' ? DS.salesRev[i] : 0)),
  q1: quartileInc(DS.checks.rows.map(x => x[1]), 0.25),
  top2: (() => { const m = {}; S.forEach((x, i) => m[x[4]] = (m[x[4]] || 0) + DS.salesRev[i]); const v = Object.values(m).sort((a, b) => b - a); return (v[0] + v[1]) / ANS.revenue * 100; })(),
  bishPlanShare: DS.plan.rows[0][3] / sum(DS.plan.rows.map(x => x[3])) * 100,
  avgAbs: (() => { const v = DS.dyn.rows.map(x => x[1]); return (v[v.length - 1] - v[0]) / (v.length - 1); })(),
  shopCorr: correl(DS.shops.rows.map(x => x[1]), DS.shops.rows.map(x => x[4])),
  shopR2: olsR2(DS.shops.rows.map(x => x[4]), [DS.shops.rows.map(x => x[1]), DS.shops.rows.map(x => x[3])]),
  decIdx: (() => { const y = DS.monthly.rows.map(x => x[2]); return (y[11] + y[23]) / 2 / mean(y) * 100; })(),
  pmt: (() => { const r = 0.18 / 12; return 500000 * r / (1 - Math.pow(1 + r, -24)); })(),
  transport: (() => { const c = DS.transport.rows; let best = Infinity; for (let a1 = 0; a1 <= 70; a1++) for (let a2 = 0; a2 <= 60; a2++) { const a3 = 120 - a1 - a2; if (a3 < 0 || a3 > 70) continue; const b1 = 70 - a1, b2 = 60 - a2, b3 = 70 - a3; if (b1 + b2 + b3 !== 80) continue; best = Math.min(best, a1 * c[0][1] + a2 * c[0][2] + a3 * c[0][3] + b1 * c[1][1] + b2 * c[1][2] + b3 * c[1][3]); } return best; })(),
  osh: regRev('Ош'),
  pq: correl(S.map(x => x[7]), S.map(x => x[6]))
});

