    { q: 'Какой функцией удобно считать общую стоимость перевозок?', o: ['СУММПРОИЗВ', 'СУММЕСЛИ', 'МУМНОЖ', 'СЧЁТ'], a: 0, e: 'Попарные произведения стоимостей и объёмов.' }
