/* ---------- 40 пар (2 пары по каждой из 20 тем) ---------- */
const SESSIONS = [];
LESSONS.forEach(L => {
  const p1 = { ...L, n: L.n * 2 - 1, topic: L.n, part: 1, topicTitle: L.title };
  if (L.n === 9) p1.plan = plan('Правила выбора диаграмм, оформление, спарклайны.', 'Четыре типа диаграмм и спарклайны по данным продаж.', 'Отчёт с тремя диаграммами и выводами.', 'Показ диаграмм и обоснование выбора типа.');
  if (L.n === 9) p1.solo = 'Подготовьте лист-отчёт по продажам с тремя корректно выбранными диаграммами и выводом под каждой (1–2 предложения). Это подготовка к рубежному контролю 1 на следующей паре.';
  if (L.n === 19) p1.plan = plan('Google Таблицы, функции QUERY/FILTER/UNIQUE, совместный доступ; защита в Excel.', 'Перенос анализа продаж в Google Таблицы, совместный доступ, защита файла.', 'Задание в Google Таблицах с настройкой доступа.', 'Показ таблицы и настроек доступа.');
  if (L.n === 19) p1.solo = 'Выполните одно из прошлых заданий (сводная таблица или прогноз) полностью в Google Таблицах и настройте совместный доступ. Пришлите ссылку с правами «Комментатор». Рубежный контроль 2 — на следующей паре.';
  if (L.n === 20) p1.plan = [[10, 'Постановка задачи', 'Выбор варианта набора данных, формулировка 4–5 вопросов анализа.'], [65, 'Выполнение работы', 'Очистка и обработка, сводная таблица, диаграммы, статистические показатели.'], [30, 'Оформление отчёта', 'Лист «Отчёт»: ключевые показатели, 3 диаграммы, выводы.'], [15, 'Консультация', 'Проверка промежуточного результата преподавателем.']];
  if (L.n === 20) p1.steps = L.steps.slice(0, 7);
  const P = PART2[L.n];
  const p2 = { ...P, n: L.n * 2, topic: L.n, part: 2, week: L.week, module: L.module, topicTitle: L.title };
  delete p1.defense;
  SESSIONS.push(p1, p2);
});

