let done = store.get('done40', []);
let stepsState = store.get('steps40', {});
const isDone = n => done.includes(n);
function toggleDone(n) { done = isDone(n) ? done.filter(x => x !== n) : [...done, n]; store.set('done40', done); updateProgress(); }
function updateProgress() {
  $('#progressText').textContent = `${done.length} / ${SESSIONS.length}`;
  $('#progressFill').style.width = (done.length / SESSIONS.length * 100) + '%';
}
function toast(msg) { const t = $('#toast'); t.textContent = msg; t.classList.add('show'); clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('show'), 1800); }
function copyText(text) {
  const fallback = () => { const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) { } ta.remove(); };
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(() => toast('Скопировано'), () => { fallback(); toast('Скопировано'); });
  else { fallback(); toast('Скопировано'); }
}
const cellOut = v => typeof v === 'number' ? String(v).replace('.', ',') : String(v);
function tableToTSV(ds) { return [ds.cols, ...ds.rows].map(r => r.map(cellOut).join('\t')).join('\r\n'); }
function downloadCSV(ds) {
  const csv = '﻿' + [ds.cols, ...ds.rows].map(r => r.map(v => { const s = cellOut(v); return /[;"\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }).join(';')).join('\r\n');
  const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); a.download = ds.name + '.csv'; document.body.appendChild(a); a.click(); a.remove();
}
const colLetter = i => String.fromCharCode(65 + i);

