function heroChart() {
  const v = DS.monthly.rows.map(r => r[2]), W = 360, H = 200, p = 26, mn = Math.min(...v) - 20, mx = Math.max(...v) + 20;
  const x = i => p + i * (W - 2 * p) / (v.length - 1), y = val => H - p - (val - mn) / (mx - mn) * (H - 2 * p);
  const t = DS.monthly.rows.map(r => r[0]), b = slope(v, t), a = intercept(v, t);
  const line = v.map((val, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(val).toFixed(1)}`).join(' ');
  const bars = v.map((val, i) => `<rect x="${(x(i) - 4).toFixed(1)}" y="${y(val).toFixed(1)}" width="8" height="${(H - p - y(val)).toFixed(1)}" rx="2" fill="var(--accent-soft)"/>`).join('');
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Пример: продажи по месяцам и линейный тренд">
  ${bars}<path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2.2"/>
  <line x1="${x(0)}" y1="${y(a + b)}" x2="${x(23)}" y2="${y(a + b * 24)}" stroke="var(--warn)" stroke-width="2" stroke-dasharray="5 4"/>
  <text x="${p}" y="16" font-size="11" fill="var(--ink-3)" font-family="var(--font)">Продажи по месяцам и тренд ŷ = ${fmt(a, 0)} + ${fmt(b, 1)}·t</text></svg>`;
}

function timelineHTML(pl, compact) {
  let t = 0;
  const bar = `<div class="tl-bar">${pl.map((p, i) => `<span style="flex:${p[0]};background:${PLAN_COLORS[i % 5]}" title="${esc(p[1])}"></span>`).join('')}</div>`;
  const rows = pl.map((p, i) => { const s = t; t += p[0]; return `<div class="tl-row"><div class="tl-time">${s}–${t} мин</div><div class="tl-dot" style="background:${PLAN_COLORS[i % 5]}"></div><div class="tl-text"><b>${esc(p[1])}</b>${compact ? '' : `<span>${esc(p[2])}</span>`}</div></div>`; }).join('');
  return bar + `<div class="timeline">${rows}</div>`;
}

let filterModule = 0, filterText = '';
function renderPractice() {
  main.innerHTML = `<div class="eyebrow">Практические занятия · 40 пар × 2 часа = 80 часов</div><h1>Практикум</h1>
  <p class="lead">Каждая тема — две пары. Прогресс по шагам и отметки о выполнении сохраняются в этом браузере.</p>
  <div class="filters"><input class="search" id="q" type="search" placeholder="Поиск по темам и функциям: ВПР, сводная, корреляция…" value="${esc(filterText)}">
  <button class="chip ${filterModule === 0 ? 'on' : ''}" data-m="0">Все</button><button class="chip ${filterModule === 1 ? 'on' : ''}" data-m="1">Модуль 1</button><button class="chip ${filterModule === 2 ? 'on' : ''}" data-m="2">Модуль 2</button></div>
  <div id="list"></div>`;
  const draw = () => {
    const q = filterText.toLowerCase();
    const items = SESSIONS.filter(l => (!filterModule || l.module === filterModule) && (!q || (l.topicTitle + ' ' + l.title + ' ' + l.short + ' ' + l.theory + ' ' + l.formulas.map(f => f[0]).join(' ')).toLowerCase().includes(q)));
    const card = l => `<a class="lesson-card ${isDone(l.n) ? 'done' : ''}" href="#/lesson/${l.n}"><div class="lc-top"><span>Пара ${l.n} · неделя ${l.week}</span>${isDone(l.n) ? '<span class="done-badge">✓ выполнено</span>' : `<span>${l.part === 1 ? 'основы' : 'закрепление'}</span>`}</div><div class="lc-title">${esc(l.part === 1 ? l.title.replace(/\. Рубежный контроль \d/, '') : l.title)}</div><div class="lc-sub">${esc(l.short)}</div></a>`;
    let html = '';
    [1, 2].forEach(m => {
      const mi = items.filter(l => l.module === m); if (!mi.length) return;
      html += `<div class="module-title"><h2>Модуль ${m}</h2><span class="muted">${m === 1 ? 'Обработка и обобщение данных в Excel' : 'Статистический анализ, прогноз и решения'}</span></div>`;
      [...new Set(mi.map(l => l.topic))].forEach(t => {
        html += `<h3 class="topic-h">Тема ${t}. ${esc(LESSONS[t - 1].title)}</h3><div class="grid grid-2">${mi.filter(l => l.topic === t).map(card).join('')}</div>`;
      });
    });
    $('#list').innerHTML = html || '<p class="muted">Ничего не найдено.</p>';
  };
  draw();
  $('#q').addEventListener('input', e => { filterText = e.target.value; draw(); });
  $$('.chip[data-m]').forEach(b => b.addEventListener('click', () => { filterModule = +b.dataset.m; $$('.chip[data-m]').forEach(x => x.classList.toggle('on', x === b)); draw(); }));
}

function datasetHTML(key, idx) {
  const list = key === 'branches' ? DS.branches : [DS[key]];
  return list.map((ds, j) => {
    const id = `${key}_${j}`;
    const head = `<tr><th class="rh"></th>${ds.cols.map((_, i) => `<th class="colh">${colLetter(i)}</th>`).join('')}</tr><tr><td class="rh">1</td>${ds.cols.map(c => `<th>${esc(c)}</th>`).join('')}</tr>`;
    const body = ds.rows.map((r, ri) => `<tr><td class="rh">${ri + 2}</td>${r.map(v => `<td class="${typeof v === 'number' ? 'n' : ''}">${typeof v === 'number' ? (Number.isInteger(v) && v > 2100 ? fmt(v) : String(v).replace('.', ',')) : esc(v).replace(/ /g, '&nbsp;')}</td>`).join('')}</tr>`).join('');
    return `<div class="ds-title">${esc(ds.title)} <span class="muted">· ${ds.rows.length} строк</span></div>
    <div class="btn-row"><button class="btn small" data-copy="${id}">📋 Копировать для Excel</button><button class="btn small" data-csv="${id}">⬇ Скачать CSV</button></div>
    <div class="table-wrap"><table class="data"><thead>${head}</thead><tbody>${body}</tbody></table></div>`;
  }).join('');
}
function dsById(id) { const [k, j] = id.split('_'); return k === 'branches' ? DS.branches[+j] : DS[k]; }

