/* =====================================================================
   МАРШРУТИЗАЦИЯ И ЗАПУСК
   ===================================================================== */
function route() {
  const h = location.hash.replace(/^#\/?/, ''), [p, a] = h.split('/');
  clearInterval(timerH);
  const map = { '': 'home', practice: 'practice', lesson: 'practice', lectures: 'lectures', test: 'test', srs: 'srs', questions: 'questions', grading: 'grading', literature: 'literature' };
  $$('#nav a').forEach(x => x.classList.toggle('active', x.dataset.route === (map[p] || 'home')));
  if (p === 'lesson') renderLesson(+a);
  else if (p === 'practice') renderPractice();
  else if (p === 'lectures') renderLectures();
  else if (p === 'test') renderTest(+a === 2 ? 2 : 1);
  else if (p === 'srs') renderSRS();
  else if (p === 'questions') renderQuestions();
  else if (p === 'grading') renderGrading();
  else if (p === 'literature') renderLiterature();
  else renderHome();
  $('#side').classList.remove('open');
  window.scrollTo(0, 0); main.focus({ preventScroll: true });
}

(function init() {
  const theme = store.get('theme', null); if (theme) document.documentElement.dataset.theme = theme;
  $('#themeBtn').addEventListener('click', () => {
    const cur = document.documentElement.dataset.theme || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
    const nt = cur === 'dark' ? 'light' : 'dark'; document.documentElement.dataset.theme = nt; store.set('theme', nt);
  });
  $('#menuBtn').addEventListener('click', () => $('#side').classList.toggle('open'));
  window.addEventListener('hashchange', route);
  updateProgress(); route();
})();
